"""Door task controller for the Unitree H1 service. Targets are normalized joint positions."""
from rcb_client import Robot
import numpy as np
from PIL import Image
CAMERAS=['left_eye_camera','right_eye_camera','room_camera']
def save_obs(obs,prefix='obs'):
    for name,frame in obs.last.items(): Image.fromarray(frame).save(f'/app/output/{prefix}_{name}.png')
def normalized_targets(spec,radians):
    rr=np.asarray(spec['action_types']['joint_position']['range_rad'],float)
    return np.clip(2*(np.asarray(radians)-rr[:,0])/(rr[:,1]-rr[:,0])-1,-1,1)
def run():
    r=Robot();s=r.spec();r.reset(cameras=CAMERAS)
    q=np.zeros(19);q[[2,7]]=.10;q[[3,8]]=.90;q[[4,9]]=-.18
    a=normalized_targets(s,q)
    for j in range(5):
        res=r.submit('joint_position',np.tile(a,(25,1)),dt=.02,interpolate='hold',cameras=['room_camera'],video='none')
        p=np.asarray(res.meta['proprio']['now']);print('t',res.meta['sim_time_s'],'done',res.meta['done'],res.meta['reason'],'q',np.round(p[:19],2).tolist(),'imu',np.round(p[38:],2).tolist())
        if res.done:break
    save_obs(res,'positive_hip_stance');print('status',r.status())
if __name__=='__main__':run()
